import{_ as o,o as e,c as r,a2 as l}from"./chunks/framework.mRCPFc5l.js";const A=JSON.parse('{"title":"Re_ADOJAS：谱面播放器","description":"","frontmatter":{"title":"Re_ADOJAS：谱面播放器","order":3},"headers":[],"relativePath":"zh/mods/online-tools/re_adojas.md","filePath":"zh/mods/online-tools/re_adojas.md","lastUpdated":1786943111000}'),t={name:"zh/mods/online-tools/re_adojas.md"};function i(s,a,n,d,_,h){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="re-adojas-谱面播放器" tabindex="-1">Re_ADOJAS：谱面播放器 <a class="header-anchor" href="#re-adojas-谱面播放器" aria-label="Permalink to &quot;Re_ADOJAS：谱面播放器&quot;">​</a></h1><p><a href="/tools/re_adojas/">Re_ADOJAS</a> 是一个基于 <a href="./../../libs/adofai-js/">ADOFAI-JS</a> 的轻量级 ADOFAI 谱面播放器，支持多平台运行。</p><h2 id="功能一览" tabindex="-1">功能一览 <a class="header-anchor" href="#功能一览" aria-label="Permalink to &quot;功能一览&quot;">​</a></h2><ul><li><strong>谱面加载</strong>：支持 <code>.adofai</code>、<code>.json</code>、<code>.zip</code> 关卡文件</li><li><strong>渲染</strong>：WebGL 与 WebGPU（实验性），支持 Web Worker 多线程渲染</li><li><strong>主题</strong>：浅色 / 深色 / 跟随系统</li><li><strong>媒体导入</strong>：音频、视频背景、装饰图片、背景图片</li><li><strong>性能</strong>：可调节目标帧率，同步 / 异步渲染，多种关卡加载方式</li><li><strong>视觉效果</strong>：星球拖尾、打击音效、谱面信息指示（TBPM / CBPM / Map Time / Tiles）</li><li><strong>其他</strong>：全屏模式、FPS 显示、性能监控面板</li><li><strong>国际化</strong>：简体中文、英语、日语</li></ul><h2 id="使用步骤" tabindex="-1">使用步骤 <a class="header-anchor" href="#使用步骤" aria-label="Permalink to &quot;使用步骤&quot;">​</a></h2><ol><li>打开 <a href="/tools/re_adojas/">Re_ADOJAS</a></li><li>加载谱面文件（可直接拖入窗口）</li><li>如有需要，导入音频、视频背景等资源</li><li>开始播放</li></ol><h2 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to &quot;提示&quot;">​</a></h2><ul><li>大谱面建议使用 Worker 或异步加载方式</li></ul>',8)])])}const f=o(t,[["render",i]]);export{A as __pageData,f as default};
